import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { Toaster } from 'react-hot-toast';
import Header from './components/Header';
import UserModeSelector from './components/UserModeSelector';
import HomePage from './pages/HomePage';
import PredictionWorkflow from './pages/PredictionWorkflow';
import HelpPage from './pages/HelpPage';
import { UserMode, AppState } from './types';
import { ApiService } from './services/api';

function App() {
  const [appState, setAppState] = useState<AppState>({
    userMode: 'patient',
    currentStep: 'upload',
    isLoading: false,
  });

  const [isBackendReady, setIsBackendReady] = useState<boolean | null>(null);

  // Check backend health on app load
  useEffect(() => {
    const checkBackend = async () => {
      try {
        await ApiService.healthCheck();
        setIsBackendReady(true);
      } catch (error) {
        console.error('Backend health check failed:', error);
        setIsBackendReady(false);
      }
    };

    checkBackend();
  }, []);

  const updateAppState = (updates: Partial<AppState>) => {
    setAppState(prev => ({ ...prev, ...updates }));
  };

  const handleUserModeChange = (mode: UserMode) => {
    setAppState(prev => ({
      ...prev,
      userMode: mode,
      currentStep: 'upload',
      features: undefined,
      handwritingImage: undefined,
      prediction: undefined,
      error: undefined,
    }));
  };

  const resetWorkflow = () => {
    setAppState(prev => ({
      ...prev,
      currentStep: 'upload',
      features: undefined,
      handwritingImage: undefined,
      prediction: undefined,
      error: undefined,
      isLoading: false,
    }));
  };

  // Show backend connection status
  if (isBackendReady === null) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="loading-spinner mx-auto mb-4"></div>
          <h2 className="text-xl font-semibold text-gray-900 mb-2">Connecting to Server</h2>
          <p className="text-gray-600">Please wait while we establish connection...</p>
        </div>
      </div>
    );
  }

  if (isBackendReady === false) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="max-w-md mx-auto text-center p-6 bg-white rounded-lg shadow-md">
          <div className="w-12 h-12 mx-auto mb-4 bg-red-100 rounded-full flex items-center justify-center">
            <svg className="w-6 h-6 text-red-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L3.732 16.5c-.77.833.192 2.5 1.732 2.5z" />
            </svg>
          </div>
          <h2 className="text-xl font-semibold text-gray-900 mb-2">Server Connection Failed</h2>
          <p className="text-gray-600 mb-4">
            Unable to connect to the prediction server. Please ensure the backend is running on port 9000.
          </p>
          <button 
            onClick={() => window.location.reload()}
            className="btn-primary"
          >
            Try Again
          </button>
        </div>
      </div>
    );
  }

  return (
    <Router>
      <div className="min-h-screen bg-gray-50">
        <Header 
          userMode={appState.userMode}
          onReset={resetWorkflow}
        />
        
        <main className="container mx-auto px-4 py-6">
          <Routes>
            <Route 
              path="/" 
              element={
                <HomePage 
                  userMode={appState.userMode}
                  onUserModeChange={handleUserModeChange}
                />
              } 
            />
            <Route 
              path="/predict" 
              element={
                <PredictionWorkflow 
                  appState={appState}
                  updateAppState={updateAppState}
                />
              } 
            />
            <Route 
              path="/help" 
              element={<HelpPage userMode={appState.userMode} />} 
            />
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </main>

        {/* Global notifications */}
        <Toaster
          position="top-right"
          toastOptions={{
            duration: 4000,
            style: {
              background: '#363636',
              color: '#fff',
            },
            success: {
              duration: 3000,
              iconTheme: {
                primary: '#10B981',
                secondary: '#fff',
              },
            },
            error: {
              duration: 5000,
              iconTheme: {
                primary: '#EF4444',
                secondary: '#fff',
              },
            },
          }}
        />
      </div>
    </Router>
  );
}

export default App;